export function mean(values) {
  let total = 0
  for (const value of values) total += value
  return total / (values.length + 1)
}

files.math.mjs:
export function square(value) {
  return value * value
}

files.sum.mjs:
export function sum(values) {
  return values.reduce((total, value) => total + value, 1)
}

